import {test} from 'node:test';
import assert from 'node:assert/strict';
import {researchReadiness} from '../shared/research-readiness.mjs';
import {COMPANY_ANALYSIS_FIELDS} from '../shared/company-directory.mjs';
const complete=()=>({version:3,evidence:[{id:'source',verification:'unverified'}],claims:[],hypothesis:{action:'observe',logic:'Uncertain mechanism',invalidation:'Contrary evidence',reviewAt:'2026-10-05',holdingHorizon:'One week'},nextEvidence:'Check statement',companies:[{symbol:'TEST.US',analysis:Object.fromEntries(Object.keys(COMPANY_ANALYSIS_FIELDS).map(k=>[k,'Unknown; verify using statement']))}]});
test('observation can be documented without changing evidence or granting approval',()=>{const t=complete(),before=structuredClone(t),r=researchReadiness(t);assert.equal(r.status,'documented');assert.equal(r.automaticApproval,false);assert.deepEqual(t,before);});
test('actionable research requires trigger and company analysis',()=>{const t=complete();t.hypothesis.action='buy';t.companies[0].analysis={};const r=researchReadiness(t);assert(r.gaps.some(g=>g.id==='trigger'));assert.equal(r.gaps.filter(g=>g.target==='companies').length,7);});
test('broken citations and incomplete probabilities remain incomplete',()=>{const t=complete();t.claims=[{id:'c',claim:'Outcome',evidenceIds:['gone'],probability:50}];const r=researchReadiness(t);assert.equal(r.status,'incomplete');assert(r.gaps.some(g=>g.id==='citation:c'));assert(r.gaps.some(g=>g.id==='probability:c'));});
test('removed companies do not satisfy company requirement',()=>{const t=complete();t.companies=[];assert(researchReadiness(t).gaps.some(g=>g.id==='companies'));});
import {validateDossierSections} from '../shared/research-dossier.mjs';
import {openStore} from '../server/store.mjs';
import {openResearch} from '../server/research.mjs';
test('dossier validation rejects malformed sections, missing citations and mismatched table cells',()=>{for(const sections of [null,[{}],[{id:'s',title:'T',paragraphs:['P'],sourceIds:['gone']}],[{id:'s',title:'T',paragraphs:['P'],sourceIds:[],table:{columns:['A'],rows:[['A','B']]}}]])assert.throws(()=>validateDossierSections(sections,[]));});
test('dossier editing versions drafts, rejects stale saves and blocks incomplete completion',()=>{const store=openStore(':memory:'),r=openResearch(store,{seed:false});try{const t=r.create({title:'Synthetic research',summary:'Synthetic hypothesis'}),dossier={sections:[{id:'s',title:'Analysis',paragraphs:['Unknown; verify source'],sourceIds:[]}],reviewStatus:'draft',revisionReason:'First draft'};const next=r.update(t.id,{version:t.version,dossier});assert.equal(next.version,2);assert.equal(next.dossier.basedOnResearchVersion,2);assert.equal(r.history(t.id).length,2);assert.throws(()=>r.update(t.id,{version:1,dossier}),/更新/);assert.throws(()=>r.update(t.id,{version:2,dossier:{...dossier,reviewStatus:'complete'}}),/补齐/);assert.equal(r.get(t.id).version,2);assert.equal(r.history(t.id)[1].topic.dossier,undefined);}finally{store.close();}});
test('test-case import rejects malformed dossier before writing',()=>{const store=openStore(':memory:'),r=openResearch(store);try{const seed=r.get('agent-cpu'),data={...seed,id:'recent-test-invalid-dossier',origin:'recent-data-test',batchId:'synthetic',inputHash:'synthetic',firstSeen:'2026-09-01T00:00:00Z',dossier:{sections:[{}]}};assert.throws(()=>r.importTestCase(data));assert.throws(()=>r.get(data.id));}finally{store.close();}});
test('complete review is version-bound and preserves prior completed dossier after later research change',()=>{const store=openStore(':memory:'),r=openResearch(store);try{const seed=r.get('agent-cpu'),t=complete();Object.assign(t,{id:'recent-test-complete',origin:'recent-data-test',batchId:'synthetic',inputHash:'complete',title:'Synthetic',summary:'Synthetic',chain:seed.chain.slice(0,3),firstSeen:'2026-09-01T00:00:00Z'});t.companies[0].symbol='AMD.US';t.companies[0].note='Synthetic relation';t.evidence=[{...seed.evidence[0],id:'source',verification:'primary',stance:'supports',step:seed.chain[0].id}];let saved=r.importTestCase(t);saved=r.update(saved.id,{version:saved.version,dossier:{sections:[{id:'s',title:'Analysis',paragraphs:['Unknown; verify'],sourceIds:['source']}],reviewStatus:'complete',revisionReason:'Checked references and unknowns'}});assert.equal(saved.dossier.reviewStatus,'complete');assert.equal(saved.dossier.basedOnResearchVersion,saved.version);const later=r.update(saved.id,{version:saved.version,nextEvidence:'New counterevidence to inspect'});assert.notEqual(later.version,later.dossier.basedOnResearchVersion);assert.equal(r.history(saved.id)[1].topic.dossier.reviewStatus,'complete');}finally{store.close();}});
import {createService} from '../server/service.mjs';
import {createHandler} from '../server/index.mjs';
test('dossier HTTP endpoint accepts bounded long drafts without changing the paper book',async()=>{const s=openStore(':memory:'),service=createService(s),handler=createHandler(s,service);try{const t=service.research.create({title:'HTTP fixture',summary:'Synthetic'}),before=service.paper.snapshot(),body={version:1,dossier:{sections:[{id:'s',title:'Analysis',paragraphs:Array.from({length:8},()=> 'Synthetic '.repeat(250)),sourceIds:[]}],reviewStatus:'draft',revisionReason:'HTTP boundary'}};let status,result;await handler({method:'POST',url:`/api/research/${t.id}/dossier`,headers:{host:'127.0.0.1:4179','content-type':'application/json'},async *[Symbol.asyncIterator](){const b=Buffer.from(JSON.stringify(body));for(let i=0;i<b.length;i+=7)yield b.subarray(i,i+7);}},{writeHead:n=>status=n,end:b=>result=JSON.parse(b)});assert.equal(status,200);assert.equal(result.research.topics.find(x=>x.id===t.id).version,2);assert.deepEqual(service.paper.snapshot(),before);}finally{await service.close();s.close();}});
test('partial first-section draft saves and restores while completion rejects empty sections',()=>{const s=openStore(':memory:'),r=openResearch(s,{seed:false});try{const t=r.create({title:'Partial draft',summary:'Synthetic'}),dossier={sections:[{id:'facts',title:'Facts',paragraphs:['First paragraph'],sourceIds:[]},{id:'impact',title:'Impact',paragraphs:[],sourceIds:[]}],reviewStatus:'draft',revisionReason:'Initial partial draft'};const saved=r.update(t.id,{version:1,dossier});assert.equal(saved.dossier.sections[0].paragraphs[0],'First paragraph');assert.deepEqual(r.get(t.id).dossier.sections[1].paragraphs,[]);assert.throws(()=>r.update(t.id,{version:2,dossier:{...dossier,reviewStatus:'complete'}}),/段落/);assert.equal(r.get(t.id).version,2);}finally{s.close();}});
